import React from "react";
import CarTypeCard from "./CarTypeCard";
import Car1 from "../../images/Car1.png"
import Car2 from "../../images/Car2.png"
import Car3 from "../../images/Car3.png"
import Car4 from "../../images/Car4.png"
import Car5 from "../../images/Car5.png"

function BrowseType() {
  return (
    <div className="BrowseType w-full h-60">
      <div className="h-10 flex justify-start pl-20">
        <h1 className="font-medium text-3xl">Browse by Type</h1>
      </div>
      
      <div className="h-48 flex justify-center items-center">
        <div className="grid grid-cols-5 gap-4 w-[90%] max-w-6xl">
          {/* Тип 1 */}
          <div className="">
            <CarTypeCard image={Car1} label="3 Cars" title="SUV" />
          </div>
          
          {/* Тип 2 */}
          <div className="">
            <CarTypeCard image={Car2} label="3 Cars" title="SUV" />
          </div>

          {/* Тип 3 */}
          <div className="">
            <CarTypeCard image={Car3} label="3 Cars" title="SUV" />
          </div>

          {/* Тип 4 */}
          <div className="">
            <CarTypeCard image={Car4} label="3 Cars" title="SUV" />
          </div>

          {/* Тип 5 */}
          <div className="">
            <CarTypeCard image={Car5} label="3 Cars" title="SUV" />
          </div>
        </div>
      </div>
    </div>
  );
}

export default BrowseType;
